contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address other, uint value) public {
        require(other != address(this));
        require(other != address(c));
        uint balBefore = address(c).balance;
        bool reverted;
        // temporarily change msg.sender? We cannot change msg.sender directly in Solidity.
        // Instead, we rely on the fact that the test contract is not the owner for this call?
        // Actually the test contract deployed c, so it is the owner. To test non-owner revert, we need a call from a different address.
        // But we can only interact via the test contract. The rule must be about calls from the test contract.
        // The focus says: "write the rule about whether a call withdraw(args) reverts or completes, and on which inputs"
        // The previous rule was about owner calling withdraw. The new rule should be different.
        // What about: withdraw(value) reverts when value > balance, regardless of owner? That was tried.
        // Let's think: The accepted rules include one about owner calling withdraw when c holds at least value: does not revert and balance decreases.
        // So the complementary rule: when owner calls withdraw(value) with value > balance, it always reverts and balance unchanged.
        // That is a general rule: for any value > balance, withdraw reverts.
        // Let's test that.
        // We need to ensure we call withdraw with value > balance. So require(value > balBefore).
        // But we must not require on c's state before the call that creates it? We are reading balBefore, that's fine.
        // The rule: if value > balBefore, then withdraw reverts and balance remains balBefore.
        require(value > balBefore);
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && address(c).balance == balBefore);
    }
}

